"""Responsabilidad Personal y Social EPJA Media N1 y N2, módulo 3: metas, acciones, formación y redes de apoyo, liderazgo colaborativo. OAD-09 a OAD-12. Casos y escenas inventados, con cifras de ejemplo; sin consejo clínico, legal ni financiero."""
from __future__ import annotations

from hc_common import make_build

MATERIALS = "Papel y lápiz. Todo se resuelve con lo escrito en la ficha; los casos, nombres y cifras son inventados y de ejemplo. No se pide contar vivencias reales ni datos personales: puedes responder con un caso imaginado."
build = make_build(MATERIALS)

O9 = "EPJA-RPSO-NM1y2-OAD-09"
O10 = "EPJA-RPSO-NM1y2-OAD-10"
O11 = "EPJA-RPSO-NM1y2-OAD-11"
O12 = "EPJA-RPSO-NM1y2-OAD-12"
PRIOR = ["Ya me he propuesto cosas y he aprendido de lo que resultó y de lo que no.", "Sé que las personas somos distintas y que cada una tiene su ritmo."]


def K(oa, n, F, use, explain, vocab, worked, mistakes, T, ctx, sc, op, rf, ex_, prior=None):
    build(oa, n, F, use=use, prior=prior or PRIOR, explain=explain, vocab=vocab, worked=worked, mistakes=mistakes, T=T, ctx=ctx, sc=sc,
          op=op, reinforce=rf, extend=ex_)


