# ====================================================== OAD-12 clase 2
F = ("Ficha 11 (caso inventado). En una reunión de un comité de barrio, Gloria dice: «Necesitamos una persona que lleve la lista de asistentes». "
     "Silencio. Rodrigo piensa que puede hacerlo, pero no se anima. Gloria mira a la sala y dice con calma: «Rodrigo, ¿te parece que tú la lleves esta vez y la próxima la lleva otra persona?». "
     "Él acepta. Al terminar, ella dice: «Gracias, la lista quedó clara y ordenada».")
K(O12, 2, F,
  "Hoy aprenderé las habilidades sociales y de comunicación que ayudan a liderar un grupo: escuchar, pedir con claridad, delegar y dar retroalimentación.",
  ["Las habilidades sociales son formas de relacionarse que ayudan a convivir y trabajar con otras personas: saludar, escuchar con atención, pedir con respeto, agradecer y expresar desacuerdo sin ofender. Se aprenden y se mejoran con práctica.",
   "Liderar de forma colaborativa usa habilidades de comunicación. Delegar es entregar una tarea a otra persona con claridad: qué hacer, para cuándo y con qué ayuda. La retroalimentación es decir qué salió bien y qué se puede mejorar, hablando de hechos y no de la persona.",
   "Una buena frase para delegar es corta, respetuosa y deja espacio para responder: «¿Podrías hacer esto para el jueves?». Una buena retroalimentación nombra un hecho concreto («la lista quedó ordenada»), agradece y propone un siguiente paso si hace falta."],
  [("habilidad social", "forma de relacionarse que ayuda a convivir y trabajar con otras personas"), ("delegar", "entregar una tarea a otra persona con claridad"), ("retroalimentación", "decir qué salió bien y qué se puede mejorar"), ("escucha atenta", "poner atención a lo que otra persona dice, sin interrumpir")],
  [("Delegar con claridad", "¿Cuál es mejor para delegar: «Alguien lleve la lista» o «Rodrigo, ¿llevas la lista esta vez?»?", ["La segunda nombra a la persona y la tarea.", "Deja espacio para responder."], "La segunda"),
   ("Dar retroalimentación", "¿Cuál retroalimentación es mejor: «Está bien» o «La lista quedó ordenada y fue fácil de leer»?", ["La segunda nombra un hecho concreto.", "Permite saber qué repetir."], "La segunda")],
  [("Delegar sin decir qué, cuándo ni cómo.", "La persona no sabe qué se espera.", "Di qué hacer, para cuándo y qué ayuda hay."),
   ("Dar retroalimentación sobre la persona y no sobre el hecho.", "Los juicios generales ofenden y no ayudan a mejorar.", "Habla de lo que se hizo, no de cómo es la persona.")],
  [("abc", "{F} ¿Qué hace Gloria cuando nadie se ofrece?", "Invita a Rodrigo con una pregunta amable", "Le ordena sin preguntar", "Cancela la reunión", "Usó una pregunta respetuosa y dejó espacio para que él decidiera."),
   ("abc", "{F} ¿Qué propone Gloria para la siguiente vez?", "Que otra persona lleve la lista", "Que Rodrigo la lleve siempre", "Eliminar la lista", "Ella plantea que la tarea rote entre distintas personas."),
   ("abc", "{F} ¿Qué retroalimentación da Gloria al final?", "Reconoce que la lista quedó clara y ordenada", "Critica a Rodrigo", "No dice nada", "Nombra un hecho concreto y agradece."),
   ("abc", "Delegar es", "entregar una tarea a otra persona con claridad", "hacerlo todo uno mismo", "dejar que nadie haga nada", "Delegar es repartir el trabajo explicando qué se espera."),
   ("abc", "¿Qué debe incluir una buena delegación?", "Qué hacer, para cuándo y qué ayuda hay", "Solo la fecha", "Solo una orden sin explicación", "Esos tres datos evitan confusión sobre lo que se espera."),
   ("abc", "La retroalimentación se centra en", "hechos concretos y una propuesta de mejora", "los defectos de la persona", "comparar con otras personas", "Hablar de lo hecho ayuda a mejorar sin herir."),
   ("abc", "¿Cuál de estas es retroalimentación útil?", "«El afiche estaba claro; la próxima vez agrega la hora»", "«Qué mal hecho»", "«No sirves para esto»", "Reconoce un hecho y propone una mejora concreta."),
   ("abc", "Una habilidad social es", "escuchar con atención sin interrumpir", "evitar mirar a las personas", "hablar siempre más fuerte", "La escucha atenta ayuda a entender y a convivir."),
   ("ab", "Decir «¿Podrías hacer esto para el jueves?» es una forma de", "pedir con respeto y claridad", "dar una orden sin considerar a la persona", "Es una pregunta con tarea y fecha, que invita a responder."),
   ("abc", "{F} Rodrigo no se animaba. ¿Qué ayudó a que aceptara?", "Que lo invitaran con respeto y con apoyo para rotar la tarea", "Que le gritaran", "Que lo ignoraran", "Sentirse invitado, no presionado, le dio seguridad."),
   ("abc", "Una persona interrumpe a otra cada vez que habla. ¿Qué habilidad le falta?", "La escucha atenta", "La puntualidad", "La memoria", "Interrumpir impide entender lo que la otra persona dice."),
   ("ab", "Expresar un desacuerdo sin ofender significa", "decir qué opino y por qué, con respeto", "gritar para ganar", "El desacuerdo es válido si se dice sin agredir."),
   ("abc", "Si alguien no cumplió una tarea, ¿cómo hablar con respeto?", "«Veo que la lista no llegó; ¿qué pasó y cómo lo resolvemos?»", "«Eres irresponsable»", "«No vuelvas a participar»", "Habla del hecho y busca una solución en conjunto.")],
  ("abc", "En un equipo de un taller de ejemplo, alguien debe pedir que otra persona prepare la sala el sábado a las 10:00. ¿Cuál frase usa lo aprendido?", "«Marta, ¿podrías preparar la sala el sábado a las 10:00? Tienes las llaves disponibles»", "«Alguien prepare la sala»", "«Si no vienes, no importa»", "Nombra a la persona, la tarea, el día, la hora y la ayuda."),
  [("En Responsabilidad Personal y Social: ¿qué es delegar?", "Entregar una tarea a otra persona con claridad", "Se dice qué hacer, para cuándo y con qué ayuda."),
   ("En Responsabilidad Personal y Social: ¿qué es la retroalimentación?", "Decir qué salió bien y qué se puede mejorar", "Se habla de hechos concretos y no de cómo es la persona."),
   ("Nombra una habilidad social.", "Escuchar con atención", "Ayuda a convivir y trabajar en equipo.")],
  ("Escribe dos frases para delegar una tarea en un grupo imaginario, con persona, tarea y fecha, y una retroalimentación que mencione un hecho concreto. No uses nombres de personas reales.",
   "Delegar: «Elena, ¿puedes llevar las sillas el viernes a las 17:00?» y «Mario, ¿puedes hacer el afiche para el martes?». Retroalimentación: «El afiche quedó claro y se lee desde lejos; para la próxima agrega la fecha».",
   ["dos frases de delegación con persona, tarea y fecha", "una retroalimentación con hecho concreto", "tono respetuoso"],
   ["las frases escritas"],
   ["delegar sin fecha", "retroalimentación sobre la persona y no sobre el hecho"],
   "Pregunta: «¿Quién, qué, para cuándo y con qué ayuda?»."),
  "Escribe una frase de agradecimiento que mencione un hecho concreto.",
  "Escribe qué dirías si una persona del grupo no cumple su tarea, sin ofender y buscando una solución.")

# ====================================================== OAD-12 clase 3
F = ("Ficha 12 (caso inventado). El comité del pasaje «Los Aromos» (inventado) quiere organizar una jornada de arreglo de una pequeña plaza antes de fin de año. "
     "Personas: Alicia, que ordena bien; Bruno, que sabe de carpintería simple; Carmen, que conoce a los vecinos; Daniel, que tiene poco tiempo pero quiere ayudar. "
     "Plazo de ejemplo: seis semanas. Meta: dejar la plaza limpia y con dos bancas reparadas.")
K(O12, 3, F,
  "Hoy aplicaré el liderazgo colaborativo en una situación del barrio: repartir tareas, comunicar con respeto, hacer seguimiento y reconocer los aportes del grupo.",
  ["Para liderar un proyecto de grupo, se parte por la meta común y se pregunta quién puede aportar qué. Luego se reparten las tareas según las fortalezas y el tiempo de cada persona, se acuerdan fechas y se anota todo para que sea visible.",
   "Durante el proyecto, se hace seguimiento con reuniones cortas: ¿qué se hizo?, ¿qué falta?, ¿qué se necesita? Si una persona tiene menos tiempo, se le asigna una tarea más pequeña. Cuando algo sale bien, se reconoce con nombre y hecho concreto.",
   "Si hay un desacuerdo, se escucha a cada persona, se vuelve a la meta común y se busca una solución que sirva al grupo. Liderar colaborativamente no significa que todo salga perfecto, sino que el grupo aprenda, se apoye y llegue a la meta con respeto."],
  [("proyecto", "conjunto de tareas organizadas para lograr una meta en un plazo"), ("seguimiento", "revisar cada cierto tiempo cómo avanza el proyecto"), ("tarea proporcional", "tarea que se ajusta al tiempo y las fuerzas de cada persona"), ("meta común", "lo que el grupo quiere lograr junto")],
  [("Repartir según fortalezas", "En la ficha, ¿quién es buena persona para conocer a los vecinos e invitarlos?", ["Carmen conoce a los vecinos.", "Esa fortaleza sirve para invitar."], "Carmen"),
   ("Ajustar una tarea", "Daniel tiene poco tiempo. ¿Qué tarea es proporcional para él?", ["Una tarea breve, como llevar bolsas el día de la jornada.", "No se le pide algo que exija muchas horas."], "Una tarea corta y puntual")],
  [("Asignar tareas iguales a todos sin mirar sus fortalezas ni su tiempo.", "Algunas personas se sobrecargan y otras quedan sin aportar.", "Reparte según fortalezas y disponibilidad."),
   ("No hacer seguimiento.", "Se pierde el rumbo y se llega tarde.", "Revisa en reuniones cortas qué se hizo y qué falta.")],
  [("abc", "{F} ¿Cuál es la meta común?", "Dejar la plaza limpia y con dos bancas reparadas", "Hacer una fiesta", "Reparar toda la ciudad", "Está en la última frase de la ficha."),
   ("abc", "{F} ¿Quién podría encargarse de reparar las bancas?", "Bruno, por su conocimiento de carpintería simple", "Alicia, por ordenar", "Daniel, por tener poco tiempo", "La tarea coincide con la fortaleza de Bruno."),
   ("abc", "{F} ¿Quién puede encargarse de invitar a los vecinos?", "Carmen, que los conoce", "Bruno", "Daniel", "Conocer a los vecinos es una ventaja para invitar."),
   ("abc", "{F} ¿Qué tarea parece adecuada para Alicia?", "Organizar la lista de materiales y el calendario", "Reparar solo las bancas", "Ninguna", "Su fortaleza es el orden, útil para listas y calendarios."),
   ("abc", "{F} Daniel tiene poco tiempo. ¿Qué es lo más respetuoso?", "Asignarle una tarea corta y puntual", "No considerarlo", "Exigirle lo mismo que a los demás", "Una tarea proporcional permite su aporte sin sobrecargarlo."),
   ("abc", "El seguimiento de un proyecto se hace", "con reuniones cortas para ver qué se hizo y qué falta", "solo al final", "nunca", "Revisar a tiempo permite ajustar antes de que sea tarde."),
   ("abc", "Si en una reunión hay un desacuerdo sobre la fecha, lo mejor es", "escuchar a cada persona y volver a la meta común", "imponer una fecha", "cancelar el proyecto", "La meta común ayuda a buscar una solución compartida."),
   ("abc", "¿Cuál de estas es una forma de reconocer un aporte?", "«Bruno, las bancas quedaron firmes, gracias»", "«Sirves para eso»", "«Por fin hiciste algo»", "Nombra a la persona y un hecho concreto."),
   ("abc", "{F} Pasadas tres semanas, las bancas no están listas. ¿Qué es lo más colaborativo?", "Preguntar a Bruno qué necesita y ofrecer ayuda", "Culparlo", "Hacerlo todo otra persona sin avisar", "Preguntar y ofrecer ayuda mantiene el trabajo en equipo."),
   ("ab", "Liderar colaborativamente significa", "que el grupo aprenda, se apoye y llegue a la meta con respeto", "que todo salga perfecto", "Lo central es el proceso respetuoso hacia la meta."),
   ("abc", "{F} Hay seis semanas. ¿Qué conviene hacer primero?", "Reunirse, acordar tareas y fechas, y anotarlas", "Esperar a la última semana", "Comprar todo sin consultar", "Un plan acordado ordena el trabajo."),
   ("abc", "{F} Una vecina propone cambiar la fecha de la jornada. ¿Qué hace quien lidera?", "Escucha las razones y consulta al grupo", "Rechaza de inmediato", "Cancela la jornada", "Consultar al grupo es parte del liderazgo colaborativo."),
   ("abc", "Al terminar la jornada, ¿qué acción cierra bien el proyecto?", "Agradecer a cada persona y comentar qué se puede mejorar", "No decir nada", "Decir quién falló", "Reconocer y aprender del proceso cierra con respeto.")],
  ("abc", "Un comité de ejemplo debe elegir quién lleva las llaves de la sede. Tres personas dicen que no pueden por falta de tiempo. ¿Qué actitud de liderazgo colaborativo ayuda?", "Preguntar quién puede hacerlo una vez al mes y rotar la tarea", "Obligar a una persona", "Cerrar la sede", "Rotar y proporcionar la tarea reparte responsabilidad."),
  [("En Responsabilidad Personal y Social: ¿qué es una tarea proporcional?", "Una tarea que se ajusta al tiempo y a las fuerzas de la persona", "Evita sobrecargar a algunas personas con demasiadas tareas."),
   ("En un proyecto de grupo: ¿para qué sirve el seguimiento?", "Para revisar qué se hizo y qué falta", "Permite ajustar el plan a tiempo, antes de llegar tarde."),
   ("¿Cómo reconocer un aporte?", "Nombrando a la persona y un hecho concreto", "El reconocimiento específico motiva porque dice qué se hizo bien.")],
  ("Con la ficha o con un proyecto imaginado, escribe el reparto de cuatro tareas con persona, fecha y razón (qué fortaleza usa), una frase de seguimiento y una frase de reconocimiento al terminar.",
   "Tareas: Alicia, lista de materiales, semana 1, porque ordena; Bruno, reparar bancas, semana 4, por carpintería; Carmen, invitar vecinos, semana 2, porque los conoce; Daniel, llevar bolsas el día, semana 6, por poco tiempo. Seguimiento: «¿Qué falta para las bancas?». Reconocimiento: «Gracias, Bruno, las bancas quedaron firmes».",
   ["cuatro tareas con persona y fecha", "razón de cada reparto", "frase de seguimiento", "frase de reconocimiento"],
   ["el reparto de tareas", "el seguimiento y el reconocimiento"],
   ["repartir sin considerar fortalezas", "no incluir reconocimiento"],
   "Pregunta: «¿Por qué cada persona tiene esa tarea?»."),
  "Escribe un reparto de tres tareas para organizar una pequeña actividad en la cuadra imaginaria.",
  "Escribe cómo resolverías un desacuerdo entre dos personas del grupo sobre qué día hacer la jornada.")
